	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void legacyCloseDrainsUnusedTermsAndPreservesLiveDependencies(boolean inlining) throws Exception {
		writeLegacyProperties();
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		IRI predicate = vf.createIRI("urn:ownership:predicate");
		Literal component = vf.createLiteral("shared triple-term dictionary component");
		TripleTerm inner = vf.createTripleTerm(vf.createIRI("urn:ownership:inner"), predicate, component);
		TripleTerm removed = vf.createTripleTerm(vf.createIRI("urn:ownership:removed"), predicate, inner);
		TripleTerm retained = vf.createTripleTerm(vf.createIRI("urn:ownership:retained"), predicate, component);
		LmdbStoreConfig config = config().setInlineLiterals(inlining).setValueEvictionInterval(60_000L);
		LmdbStore store = new LmdbStore(directory.toFile(), config);
		store.init();
		long retainedId;
		long componentId;
		try {
			try (NotifyingSailConnection connection = store.getConnection()) {
				connection.begin();
				connection.addStatement(vf.createIRI("urn:ownership:old-row"), predicate, removed);
				connection.commit();
				connection.begin();
				connection.clear();
				connection.commit();
				connection.begin();
				connection.addStatement(vf.createIRI("urn:ownership:new-row"), predicate, retained);
				connection.addStatement(vf.createIRI("urn:ownership:direct-component"), predicate, component);
				connection.commit();
			}
			ValueStore values = (ValueStore) store.getValueFactory();
			retainedId = values.getId(retained);
			componentId = values.getId(component);
		} finally {
			store.shutDown();
		}
		assertThat(unusedIdCount())
				.as("the develop reader drains unused IDs before opening its canonical triple-term indexes")
				.isZero();
		store = new LmdbStore(directory.toFile(), config);
		store.init();
		try {
			ValueStore values = (ValueStore) store.getValueFactory();
			assertThat(values.getId(retained)).isEqualTo(retainedId);
			assertThat(values.getValue(retainedId)).isEqualTo(retained);
			assertThat(values.getId(component)).isEqualTo(componentId);
			assertThat(values.getValue(componentId)).isEqualTo(component);
		} finally {
			store.shutDown();
		}
	}

	private long unusedIdCount() throws Exception {
		long environment;
		try (MemoryStack stack = MemoryStack.stackPush()) {
			PointerBuffer handle = stack.mallocPointer(1);
			E(mdb_env_create(handle));
			environment = handle.get(0);
		}
		try {
			E(mdb_env_set_maxdbs(environment, 32));
			E(mdb_env_open(environment, directory.resolve("values").toString(), MDB_NOTLS, 0664));
			return LmdbUtil.readTransaction(environment, (stack, transaction) -> {
				int unused = LmdbUtil.openDatabaseWithTxn(transaction, "unused_ids", 0);
				MDBStat statistics = MDBStat.malloc(stack);
				E(mdb_stat(transaction, unused, statistics));
				return statistics.ms_entries();
			});
		} finally {
			mdb_env_close(environment);
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void legacyOwningCloseEndsUntrackedAndPinnedReadersBeforeReclamation(boolean pinned) throws Exception {
		writeLegacyProperties();
		StoreProperties properties = new StoreProperties(directory.toFile());
		assertThat(properties.load()).isTrue();
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		IRI predicate = vf.createIRI("urn:ownership:predicate");
		IRI oldSubject = vf.createIRI("urn:ownership:old-row");
		Literal component = vf.createLiteral("shared canonical triple-term component");
		TripleTerm removed = vf.createTripleTerm(vf.createIRI("urn:ownership:inner"), predicate, component);
		LmdbSailStore store = new LmdbSailStore(directory.toFile(), properties,
				config().setValueEvictionInterval(60_000L), false);
		try {
			try (SailSink sink = store.getExplicitSailSource().sink(IsolationLevels.READ_COMMITTED)) {
				sink.approve(oldSubject, predicate, removed, null);
				sink.approve(vf.createIRI("urn:ownership:retained-row"), predicate, component, null);
				sink.flush();
			}
			try (SailSink sink = store.getExplicitSailSource().sink(IsolationLevels.READ_COMMITTED)) {
				sink.deprecate(vf.createStatement(oldSubject, predicate, removed));
				sink.flush();
			}
			TxnManager readers = store.getTripleStore().getTxnManager();
			try (TxnManager.Txn reader = pinned ? readers.createReadTxnPinned(store.getTripleStore()::getDataRevision)
					: readers.createReadTxnUntracked()) {
				assertThat(reader.get()).isNotZero();
				store.close();
				assertThat(reader.get()).as("shutdown must end actual native reader leases").isZero();
			}
		} finally {
			store.close();
		}
		assertThat(unusedIdCount()).isZero();
		LmdbStore reopened = new LmdbStore(directory.toFile(), config());
		reopened.init();
		try (NotifyingSailConnection connection = reopened.getConnection();
				var statements = connection.getStatements(null, predicate, component, false)) {
			assertThat(statements.hasNext()).isTrue();
			assertThat(statements.next().getObject()).isEqualTo(component);
		} finally {
			reopened.shutDown();
		}
	}

